            <div className="mt-7 flex flex-wrap gap-3">
              <Link
                href={`/${locale}/courses`}
                className="premium-button focus-ring inline-flex items-center gap-2 rounded-xl bg-primary px-5 py-3 font-bold text-white"
              >
