              src={visual.src}
              alt=""
              fill
              sizes="(max-width: 1024px) calc(100vw - 2rem), 720px"
              className="object-cover"
              style={{ objectPosition: visual.objectPosition }}
            />
            <div className="absolute inset-0 bg-[linear-gradient(90deg,rgba(5,10,25,.46),transparent_62%)]" />
